from collections import deque
queue = deque()
out = []
for op, val in ops:
    if op == "push":
        queue.append(int(val))
        for _ in range(len(queue) - 1):
            queue.append(queue.popleft())
    elif op == "pop":
        out.append(queue.popleft())
    elif op == "top":
        out.append(queue[0])
    else:
        out.append("yes" if not queue else "no")
print("\n".join(map(str, out)))

