#include <string>
#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<string>> ops(n, vector<string>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ops[i][j];
        }
    }

    queue<long long> line;
    for (int i = 0; i < n; i++) {
        const string& op = ops[i][0];
        if (op == "push") {
            line.push(stoll(ops[i][1]));
            for (size_t j = 0; j + 1 < line.size(); j++) {
                line.push(line.front());
                line.pop();
            }
        } else if (op == "pop") {
            cout << line.front() << "\n";
            line.pop();
        } else if (op == "top") {
            cout << line.front() << "\n";
        } else {
            cout << (line.empty() ? "yes" : "no") << "\n";
        }
    }

    return 0;
}

