import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[][] ops = new String[(int) n][2];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        Deque<Long> line = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String op = ops[i][0];
            if (op.equals("push")) {
                line.addLast(Long.parseLong(ops[i][1]));
                for (int j = 0; j + 1 < line.size(); j++) line.addLast(line.pollFirst());
            } else if (op.equals("pop")) {
                sb.append(line.pollFirst()).append("\n");
            } else if (op.equals("top")) {
                sb.append(line.peekFirst()).append("\n");
            } else {
                sb.append(line.isEmpty() ? "yes" : "no").append("\n");
            }
        }
        System.out.print(sb);
    }
}
